const ZH_PATTERN=new RegExp(Object.keys(ZH_TERMS).sort((a,b)=>b.length-a.length).map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
function zhOriginal(s){return String(s??'').replace(ZH_PATTERN,m=>ZH_TERMS[m]);}
function zhHTML(s){return String(s).replace(/>([^<]+)</g,(_,t)=>'>'+zh(t)+'<');}

const zhCache=new Map();function zh(s){s=String(s??'');if(!/[\u3040-\u30ff]/.test(s))return s;if(zhCache.has(s))return zhCache.get(s);const value=zhOriginal(s);if(zhCache.size>4096)zhCache.clear();zhCache.set(s,value);return value}
